// Precheck admission: the deterministic skip gates the action runs before
// any model call. #961 skips draft PRs; #231 skips labeled events whose
// label is not the re-review label.

export interface PrecheckEvent {
  action: string;
  label?: string;
}

export interface PrecheckOutput {
  decision: "review" | "skip";
  skip_reason?: string;
}

export function decide(event: PrecheckEvent, pr: { draft: boolean }): PrecheckOutput {
  if (pr.draft) {
    // #961: a draft PR never reviews, whatever else the event carries.
    return { decision: "skip", skip_reason: "pr-draft" };
  }
  if (event.action === "labeled" && event.label !== "ai-review") {
    // #231: a labeled event only reviews when the label is the re-review label.
    return { decision: "skip", skip_reason: "unrelated-label" };
  }
  return { decision: "review" };
}
